def _orb(el, l):
    es = el.data.get('Electronic structure', '')
    vals = []
    if isinstance(es, dict):
        for key, occ in es.items():
            if key.startswith(l):
                vals.append(occ)
        return float(np.sum(vals)) if vals else 0.0
    return float(np.sum([o for (ll, o) in re.findall(r'([spdf])([\d.]+)', str(es)) if ll == l]))

